void playTone(int freq, int duration) {
  ledcChangeFrequency(ledChannel, freq, resolution);
  ledcWrite(ledChannel, 128);
  delay(duration);
  ledcWrite(ledChannel, 0);
  delay(100);
}

void loop() {
  playTone(1000, 500);
  playTone(1500, 500);
  delay(1000);
}

